// constat:template id=constat-phone-walks-script version=59 sha256=a160ec14b827015e442153e963f211eab1200c78769ce279c3e692c808cf9590
// Generated by DoneMark. Walks every walk in journeys/ (*.walk.yaml) on an Android emulator, in this
// app's test app opened on this attempt, photographs each step, and writes one report DoneMark reads:
// .constat/journeys/constat-journeys.json. A walk is code in this repository; DoneMark never runs one.
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const OUT = '.constat/journeys';
const WALKS = '.constat/walks';
const YAML = createRequire(import.meta.url)(process.env.CONSTAT_YAML || 'yaml');
const readJson = (path) => { try { return path ? JSON.parse(readFileSync(path, 'utf8')) : null; } catch { return null; } };
const preview = readJson(process.env.CONSTAT_PREVIEW_JSON);
const build = readJson(process.env.CONSTAT_PHONE_BUILD_JSON);
const slug = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 80) || 'walk';
mkdirSync(OUT, { recursive: true });
mkdirSync(WALKS, { recursive: true });

// Which of DoneMark's walks this is: its own stamp, line 1 of this very file (template 59). The page says
// when DoneMark's walk has changed since, and offers to walk the attempt again.
const STAMP = (() => {
  try {
    const first = readFileSync(fileURLToPath(import.meta.url), 'utf8').split('\n')[0];
    const m = /constat:template id=constat-phone-walks-script version=(\d+) sha256=([0-9a-f]{64})/.exec(first);
    return m ? { version: Number(m[1]), sha256: m[2] } : null;
  } catch { return null; }
})();

const report = {
  schema: 'constat.journeys/v1',
  commit: process.env.GITHUB_SHA || null,
  url: preview && preview.manifestUrl ? preview.manifestUrl : null,
  // The commit the opened update was published for: the preview job published it from this commit.
  copyAnswered: preview && preview.commit ? preview.commit : null,
  ranAt: new Date().toISOString(),
  walkedOn: 'android',
  walkedWith: STAMP,
  // 'main' when the job took this walk from the app's merged main, 'branch' while main had none yet.
  walkFrom: process.env.CONSTAT_WALK_FROM || null,
  journeys: [],
};
const finish = (notWalked) => {
  if (notWalked) report.notWalked = notWalked;
  writeFileSync(join(OUT, 'constat-journeys.json'), JSON.stringify(report, null, 2) + '\n');
  console.log(notWalked ? 'Not walked: ' + notWalked : 'Walked ' + report.journeys.length + ' walk(s) on Android.');
  process.exit(0);
};

if (!preview || !preview.manifestUrl) finish('this attempt was not published, so there is nothing to open');
if (process.env.CONSTAT_NOT_WALKED) finish(process.env.CONSTAT_NOT_WALKED);
if (!build) finish('there is no test app built yet');
if (build.runtimeVersion && preview.runtimeVersion && build.runtimeVersion !== preview.runtimeVersion) {
  finish('this attempt needs a new test app: it carries runtime ' + preview.runtimeVersion + ', the test app ' + build.runtimeVersion);
}
if (!preview.scheme) finish('the app names no scheme, so its preview cannot be opened');
const files = existsSync('journeys') ? readdirSync('journeys').filter((f) => f.endsWith('.walk.yaml')).sort() : [];
if (files.length === 0) finish('this attempt has no walk in journeys/');

const link = preview.scheme + '://expo-development-client/?url=' + encodeURIComponent(preview.manifestUrl) + '&disableOnboarding=1';
// Each walk's own opening photograph, by name: a walk is never taken to have opened on another's.
const opening = (stem) => [
  { retry: { maxRetries: 4, commands: [
    { openLink: link },
    { extendedWaitUntil: { visible: 'DoneMark · Try.*', timeout: 45000 } },
  ] } },
  { runFlow: { when: { visible: 'This is the developer menu.*' }, commands: [{ tapOn: 'Continue' }, { pressKey: 'back' }] } },
  // DoneMark's strip aside, if it can be (final review, 12 October 2026): a strip drawn otherwise, or
  // already hidden, is no reason to read the app as failing. Then the photograph that says it opened.
  { tapOn: { text: 'Hide', optional: true } },
  { takeScreenshot: '00-opened-' + stem },
];
const INPUT_KINDS = ['inputText', 'inputRandomText', 'inputRandomEmail', 'inputRandomPersonName', 'inputRandomNumber', 'eraseText'];
const COULD_NOT_OPEN = 'the test app could not open this attempt';
// The app's Android name, from its config, when a walk does not name it and the job does not either.
const APP_ID = process.env.CONSTAT_APP_ID || (() => {
  for (const path of ['app.json', 'app.config.json']) {
    const config = readJson(path);
    const expo = config && (config.expo || config);
    if (expo && expo.android && typeof expo.android.package === 'string') return expo.android.package;
  }
  return null;
})();

// What a step is called on the record: what a person did, never what they typed.
const kindOf = (c) => (typeof c === 'string' ? c : c && typeof c === 'object' ? Object.keys(c)[0] || 'step' : 'step');
const targetOf = (v) => (typeof v === 'string' ? v
  : v && typeof v === 'object' ? (v.text ?? v.id ?? (v.element !== undefined ? targetOf(v.element) : null) ?? null) : null);
const quoted = (t) => (t ? ' “' + t + '”' : '');
function titleOf(c) {
  const kind = kindOf(c);
  const v = c && typeof c === 'object' ? c[kind] : null;
  switch (kind) {
    case 'tapOn': case 'doubleTapOn': case 'longPressOn': return 'tap' + quoted(targetOf(v));
    case 'inputText': case 'inputRandomText': case 'inputRandomEmail': case 'inputRandomPersonName': case 'inputRandomNumber': return 'type text';
    case 'eraseText': return 'erase text';
    case 'assertVisible': return 'expect' + quoted(targetOf(v));
    case 'assertNotVisible': return 'expect no' + quoted(targetOf(v));
    case 'extendedWaitUntil': return v && v.visible !== undefined ? 'expect' + quoted(targetOf(v.visible))
      : v && v.notVisible !== undefined ? 'expect no' + quoted(targetOf(v.notVisible)) : 'wait';
    case 'scrollUntilVisible': return 'scroll to' + quoted(targetOf(v));
    case 'hideKeyboard': return 'hide the keyboard';
    case 'pressKey': return 'press ' + String(v).toLowerCase();
    case 'back': return 'press back';
    default: return kind.replace(/([A-Z])/g, ' $1').toLowerCase();
  }
}

// What a step taps is scrolled to first, by DoneMark (ClassMe's first walk, 12 October 2026: the agent
// tapped "Create a profile" below the fold and every walk stopped on the login screen). Optional, and part
// of the step it comes before: no step and no photograph of its own, and where the thing is nowhere, the
// tap itself says so.
function scrolledTo(c) {
  if (kindOf(c) !== 'tapOn') return [];
  const v = c.tapOn;
  const element = typeof v === 'string' ? { text: v }
    : v && typeof v === 'object' && typeof v.text === 'string' ? { text: v.text, ...(v.index !== undefined ? { index: v.index } : {}) } : null;
  return element ? [{ scrollUntilVisible: { element, direction: 'DOWN', timeout: 8000, optional: true } }] : [];
}

/** The newest file of this name under any of these folders: Maestro writes where its version chooses. */
function newest(roots, wanted, since = 0) {
  let best = null;
  const walk = (dir, depth) => {
    if (depth > 6 || !existsSync(dir)) return;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const at = join(dir, entry.name);
      if (entry.isDirectory()) walk(at, depth + 1);
      else if (wanted(entry.name)) {
        const when = statSync(at).mtimeMs;
        if (when >= since && (!best || when > best.when)) best = { at, when };
      }
    }
  };
  for (const root of roots) walk(root, 0);
  return best ? best.at : null;
}

const pad = (n) => String(n).padStart(2, '0');
// A walk that cannot be run at all still ends in a report that says so: never a red job, never silence.
try {
for (const [j, file] of files.entries()) {
  const started = Date.now();
  const docs = YAML.parseAllDocuments(readFileSync(join('journeys', file), 'utf8')).map((d) => d.toJSON());
  const header = docs.length > 1 && docs[0] && typeof docs[0] === 'object' ? docs[0] : {};
  const steps = (Array.isArray(docs[docs.length - 1]) ? docs[docs.length - 1] : [])
    .filter((c) => c !== null && c !== undefined && kindOf(c) !== 'takeScreenshot' && kindOf(c) !== 'launchApp' && kindOf(c) !== 'openLink');
  const name = typeof header.name === 'string' && header.name.trim() ? header.name.trim() : file.replace(/\.walk\.yaml$/, '');
  const stem = slug(file.replace(/\.walk\.yaml$/, ''));
  const wrapped = [
    { appId: header.appId || APP_ID, name },
    [...opening(stem), ...steps.flatMap((c, i) => [...scrolledTo(c), c, { takeScreenshot: pad(i + 1) + '-' + stem }])],
  ];
  const flow = join(WALKS, stem + '.yaml');
  writeFileSync(flow, wrapped.map((d) => YAML.stringify(d)).join('---\n'));
  const debug = join(WALKS, 'out', stem);
  const junit = join(WALKS, 'out', stem + '.xml');
  mkdirSync(debug, { recursive: true });
  const ran = spawnSync('maestro', ['test', flow, '--debug-output', debug, '--format', 'junit', '--output', junit], { stdio: 'inherit' });
  const roots = [debug, WALKS, join(homedir(), '.maestro', 'tests')];
  const shot = (base) => newest(roots, (n) => n === base + '.png', started - 1000);
  const failure = (() => { try { return (/<failure[^>]*>([\s\S]*?)<\/failure>/.exec(readFileSync(junit, 'utf8')) || [])[1] || null; } catch { return null; } })();
  const why = (failure || 'it did not get through').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim().slice(0, 300);

  if (!shot('00-opened-' + stem)) {
    // The opening never got through: nothing of the agent's ran, so nothing of the app was judged. What
    // the phone showed instead is kept, so the person can see why; the other walks are still walked.
    const showed = newest(roots, (f) => f.endsWith('.png') && !/^\d\d-/.test(f), started - 1000);
    if (showed && !report.notWalkedPicture) { copyFileSync(showed, join(OUT, 'not-walked.png')); report.notWalkedPicture = 'not-walked.png'; }
    report.journeys.push({ file: 'journeys/' + file, name, steps: [], walkedToTheEnd: false, stopped: { step: 0, why: COULD_NOT_OPEN }, firstStepStopped: false, seconds: 0, video: null });
    continue;
  }
  const one = { file: 'journeys/' + file, name, steps: [], walkedToTheEnd: false, stopped: null, firstStepStopped: false, seconds: 0, video: null };
  const keep = (from, n) => {
    if (!from) return null;
    const to = j + '-' + stem + '-' + n + '.png';
    copyFileSync(from, join(OUT, to));
    return to;
  };
  for (const [i, c] of steps.entries()) {
    const n = i + 1;
    const photo = shot(pad(n) + '-' + stem);
    if (photo) { one.steps.push({ n, title: titleOf(c), sees: [], picture: keep(photo, n), ok: true }); continue; }
    // The first step with no photograph after it is where the walk stopped: Maestro's own photograph
    // of that moment, and its words.
    const failed = newest(roots, (f) => f.endsWith('.png') && !/^\d\d-/.test(f), started - 1000);
    one.steps.push({ n, title: titleOf(c), sees: [], picture: keep(failed, n), ok: false });
    // Where the typing itself did not go through, Maestro's words may repeat what was typed: never kept.
    one.stopped = { step: n, why: INPUT_KINDS.includes(kindOf(c)) ? 'the typing did not go through' : why };
    // Stopped before any step of the agent's went through: nothing was tried on the app yet.
    one.firstStepStopped = n === 1;
    break;
  }
  if (one.stopped === null && ran.status !== 0 && one.steps.length > 0) {
    one.steps[one.steps.length - 1].ok = false;
    one.stopped = { step: one.steps.length, why };
    one.firstStepStopped = one.steps.length === 1;
  }
  // The line is named on the last step reached, and on no step before it: DoneMark reads the first
  // step naming a line as where it was seen, so a walk that stopped must name it where it stopped.
  if (one.steps.length > 0) one.steps[one.steps.length - 1].sees = [name];
  one.walkedToTheEnd = one.stopped === null && one.steps.length === steps.length;
  one.seconds = Math.round((Date.now() - started) / 1000);
  report.journeys.push(one);
  console.log(one.stopped ? 'Stopped at step ' + one.stopped.step + ': ' + name + ': ' + one.stopped.why : 'Walked to the end: ' + name);
}
} catch (error) {
  finish('the walk could not be run: ' + String((error && error.message) || error).split('\n')[0].slice(0, 200));
}
// No walk could even be opened: the attempt was not walked, said once, with what the phone showed.
if (report.journeys.length > 0 && report.journeys.every((one) => one.steps.length === 0)) {
  report.journeys = [];
  finish(COULD_NOT_OPEN);
}
if (report.notWalkedPicture && report.journeys.some((one) => one.steps.length > 0)) delete report.notWalkedPicture;
finish(null);
